const __pageData = JSON.parse('{"title":"多表关系与表设计","description":"第 8 章的第一篇，讲表与表之间的三种关系怎么在数据库里落地——一对多在\\"多\\"的一方加字段指向\\"一\\"的一方主键，一对一再多加一个唯一约束，多对多建一张只放两个外键的中间表；再用本机实测的 1451/1452 两条报错说明外键约束拦下了什么，并对比物理外键与逻辑外键的取舍，最后按页面原型把员工模块的 emp 与 emp_expr 两张表设计出来","frontmatter":{"title":"多表关系与表设计","published":"2026-09-29T00:00:00.000Z","description":"第 8 章的第一篇，讲表与表之间的三种关系怎么在数据库里落地——一对多在\\"多\\"的一方加字段指向\\"一\\"的一方主键，一对一再多加一个唯一约束，多对多建一张只放两个外键的中间表；再用本机实测的 1451/1452 两条报错说明外键约束拦下了什么，并对比物理外键与逻辑外键的取舍，最后按页面原型把员工模块的 emp 与 emp_expr 两张表设计出来","tags":["JavaWeb","MySQL","后端"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-64-multi-table-design(1).webp","order":64,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/64-多表关系与表设计.md","filePath":"posts/学习文档/JavaWeb学习笔记/64-多表关系与表设计.md"}');
